# xbps.map — logical name -> real Void Linux package(s).
# Only rows where the name actually differs from the logical name (§1); anything
# not listed passes through unchanged (zsh, git, curl, lsd, foot, unzip,
# fontconfig, fd are all identical on xbps, so they need no row).
#
# Every row below was checked against the real repository index
# (repo-default.voidlinux.org x86_64-repodata), not from memory. See
# i3-void-packages.md for the full component -> package writeup.
#
# Only `current` may be assumed: void-repo-nonfree and void-repo-multilib are
# opt-in and off on a stock install, and os-rice does not turn them on. A name
# that exists ONLY in nonfree/multilib is therefore missing as far as a rice is
# concerned and needs a row pointing at a free equivalent in `current` (see
# `unrar` at the bottom) or no row at all (lib32-libnm, in any.map). Validating
# a row against the nonfree index is how `unrar` shipped broken.

build = base-devel
dev-headers = openssl-devel pkgconf
gh = github-cli
serie = cargo:serie          # no native serie on Void

# chafa is native and current on Void (rolling, 1.18.x) - no method row. Build
# deps only, for the provide_chafa repair path in modules/yazi.sh.
chafa-build-deps = glib-devel freetype-devel libjpeg-turbo-devel libwebp-devel tiff-devel pkg-config

# Überzug++ is in no Void repo (repology): source build only. See apt.map. Hard
# deps only - FetchContent supplies CLI11/json/fmt/spdlog/range-v3.
ueberzugpp = source:provide_ueberzugpp
ueberzugpp-build-deps = libvips-devel libsixel-devel openssl-devel tbb-devel libxcb-devel xcb-util-image-devel wayland-devel wayland-protocols extra-cmake-modules chafa-devel pkg-config

# --- X11 session core ---------------------------------------------------------
# Void does not prefix X client utilities: Arch's xorg-xrandr is just xrandr.
xorg-xinit = xinit
xorg-xrandr = xrandr
xorg-xset = xset
xorg-xsetroot = xsetroot
xorg-xprop = xprop
xorg-xev = xev
xorg-xkill = xkill
xorg-xdpyinfo = xdpyinfo
xorg-xinput = xinput
xorg-xauth = xauth
xorg-fonts-misc = font-misc-misc

# --- capitalised upstream names ----------------------------------------------
thunar = Thunar
copyq = CopyQ
mangohud = MangoHud
obs-studio = obs

# --- plain name differences ---------------------------------------------------
sshfs = fuse-sshfs
gnome-disks = gnome-disk-utility
gsimplecal = gsimplecal-gtk3
android-file-transfer = android-file-transfer-linux
gdk-pixbuf2 = gdk-pixbuf
vulkan-icd-loader = vulkan-loader
libva-mesa-driver = mesa-vaapi
noto-fonts = noto-fonts-ttf
ttf-liberation = liberation-fonts-ttf
ttf-dejavu = dejavu-fonts-ttf
nerd-fonts-symbols = nerd-fonts-symbols-ttf

# GStreamer 1.x carries the API version in the package name on Void.
gstreamer = gstreamer1
gst-plugins-base = gst-plugins-base1
gst-plugins-good = gst-plugins-good1
gst-plugins-bad = gst-plugins-bad1
gst-plugins-ugly = gst-plugins-ugly1
# No separate package: Void builds the PipeWire GStreamer element into pipewire.
gst-plugin-pipewire = pipewire

# Void ships no mesa VDPAU drivers; libvdpau-va-gl bridges VDPAU onto VA-API,
# which is what actually gets used on Intel/AMD here.
mesa-vdpau = libvdpau-va-gl

# gvfs has no NFS backend on Void (afc/afp/cdda/goa/gphoto2/mtp/smb only) —
# NFS is a kernel mount via nfs-utils, so the logical name resolves to that.
gvfs-nfs = nfs-utils

# raw-thumbnailer is absent; the gdk-pixbuf loader gives RAW previews instead,
# which is what tumbler falls back to anyway.
raw-thumbnailer = libopenraw-pixbuf-loader

# GTK theme engine + a real dark theme (adw-gtk3/Catppuccin are not packaged).
gtk-dark-theme = gnome-themes-extra gtk-engine-murrine

# --- not packaged: provider rows ---------------------------------------------
# xidlehook (the --not-when-audio idle daemon) has no Void package. This row
# makes `xidlehook` installable, but it needs a Rust toolchain, so list `rust`
# BEFORE it in a rice (§4) — which the i3 rices do. modules/i3lock.sh takes this
# route when cargo is present and falls back to the packaged xautolock when it
# is not; xautolock cannot honour audio/fullscreen inhibits, so this is the
# preferred one, not the exotic one.
xidlehook = cargo:xidlehook

# --- existing modules that assumed Arch names --------------------------------
# modules/networkmanager.sh installs `networkmanager libnm lib32-libnm`. `libnm`
# passes through (it is a real NetworkManager subpackage here). `lib32-libnm`
# does NOT get a row: Void's libnm-32bit lives in the *multilib* repo, which is
# opt-in (void-repo-multilib) and off on a stock install, so mapping it made
# every NetworkManager install fail with "libnm-32bit not found". any.map skips
# it instead - nothing in these rices is a 32-bit binary that links libnm.
networkmanager = NetworkManager
# modules/telegram.sh pulls the WebKit runtime for its built-in browser view.
webkit2gtk-4.1 = libwebkit2gtk41

# --- input, power, apps (the second i3 desktop pass) --------------------------
xorg-xmodmap = xmodmap
# Void names the LDAC codec library after the upstream project.
libldac = ldacBT

# Void drops the API version from glib's package name; the `gsettings` binary
# modules/evolution.sh drives lives in it, same as Arch's glib2. `dconf` and the
# evolution trio keep their upstream names and need no rows.
glib2 = glib

# --- yandex-browser (modules/yandex-browser.sh) -------------------------------
# Void packages no Yandex Browser (it is proprietary; not in the repo, not in
# void-packages/nonfree), and the vendor ships deb + rpm only. The builder
# unpacks the official .deb, so the shared-library closure the deb would have
# pulled in as dependencies has to be installed by name here.
yandex-browser = source:provide_yandex_browser_deb
yandex-browser-deps = bash gtk+3 nss alsa-lib libcups libXScrnSaver libXtst at-spi2-atk libxkbcommon mesa-dri libnotify desktop-file-utils hicolor-icon-theme xdg-utils libarchive

# turbostat/perf on Void.
kernel-tools = linux-tools

# Build deps for the cargo:xidlehook row above. Void keeps the XCB screensaver
# extension inside libxcb (no separate package, unlike Debian) and splits the
# PulseAudio headers into pulseaudio-devel, which is what the audio inhibit links.
xidlehook-build-deps = libxcb-devel xcb-util-devel pulseaudio-devel pkg-config

# Void's `unrar` is the nonfree upstream binary and lives in void-repo-nonfree,
# which is opt-in and off on a stock install — the same reason lib32-libnm gets
# no row above. `unar` (The Unarchiver) is in `current`, is what both archive
# GUIs modules/archives.sh installs (xarchiver, file-roller) probe for as their
# free RAR backend, and ships lsar alongside it. Same call apt.map makes with
# unrar-free: take the free extractor rather than turn on a nonfree repo behind
# the user's back.
unrar = unar

# --- second pass: names checked against the live x86_64 repodata --------------
gtk3 = gtk+3
mesa-utils = mesa-demos
nlohmann-json = json-c++
onetbb = tbb
jack2 = jack
waybar = Waybar
layer-shell-qt5 = layer-shell-qt
qt6-5compat = qt6-qt5compat
xorg-xwayland = xorg-server-xwayland
xorg-xlsclients = xlsclients
virtualbox-guest-utils = virtualbox-ose-guest
# Void ships one Nerd Fonts package rather than a package per family.
ttf-cascadia-code-nerd = nerd-fonts-ttf
ttf-cascadia-mono-nerd = nerd-fonts-ttf
ttf-iosevkaterm-nerd = nerd-fonts-ttf

# Audio. Void builds the PulseAudio and JACK replacements into `pipewire`
# itself, except the JACK client library, which is its own package.
pipewire-audio = pipewire
pipewire-pulse = pipewire
pipewire-jack = libjack-pipewire
pulseaudio-alsa = alsa-plugins-pulseaudio
# No pulseaudio-module-jack on Void; PipeWire's JACK path above is the route
# that actually works here.
pulseaudio-jack =

# --- GPU drivers --------------------------------------------------------------
vulkan-intel = mesa-vulkan-intel
vulkan-swrast = mesa-vulkan-lavapipe
# VMware/VirtualBox guests use the modesetting driver plus Mesa's vmwgfx
# gallium driver; Void packages no xf86-video-vmware DDX.
xf86-video-vmware = mesa-vmwgfx-dri
# No virtio (venus) Vulkan driver, no Amber (pre-shader R100/R200, Intel
# gen3-5) build, and no Intel compute (OpenCL/Level Zero) runtime in `current`.
vulkan-virtio =
mesa-amber =
intel-compute-runtime =
# 32-bit GL/Vulkan lives in void-repo-multilib, which is opt-in and off on a
# stock install - the same call any.map makes for lib32-libnm.
lib32-mesa =
lib32-mesa-amber =
lib32-vulkan-intel =
lib32-vulkan-virtio =
lib32-libva-intel-driver =

# --- microcode ----------------------------------------------------------------
amd-ucode = linux-firmware-amd
# Intel's microcode blob is redistributable-but-nonfree and lives in
# void-repo-nonfree, which is opt-in and off on a stock install (see the header).
# Empty RHS = skip rather than turn that repo on behind the user's back.
intel-ucode =

# --- GPaste (modules/gpaste.c) ------------------------------------------------
# Void packages libgpaste only - no daemon, no CLI, no Shell extension - so the
# source build is the route here, exactly as on apt. Same build deps as the
# apt row, under Void's -devel names.
gpaste = source:provide_gpaste
gpaste-build-deps = meson ninja pkg-config gettext gcr-devel glib-devel gtk4-devel libadwaita-devel pango-devel gobject-introspection libgirepository-devel libX11-devel libXi-devel

# zram-generator is a systemd generator; Void is runit and takes the zramen path
# in modules/swap.c instead (zramen IS packaged), so this one is a skip, not a
# gap - the mirror image of the `zramen` skip in pacman.map/dnf.map.
zram-generator =
pipewire-alsa = alsa-pipewire

# Not in void-packages: skip rather than fail the whole install step.
bibata-cursor-theme =
gtklock-userinfo-module =
libdeep-filter-ladspa =
nwg-displays =
zam-plugins =

# Void spells LuaJIT with its upstream capitalization.
cuik-build-deps = LuaJIT ninja nasm clang lld
